import{z as B,x as l,o as r,c as F,q as n,j as o,D as e,d as s,s as i,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"跨时钟域 FIFO","description":"","frontmatter":{"title":"跨时钟域 FIFO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/async-fifo-cdc.md","filePath":"cs/async-fifo-cdc.md","lastUpdated":1791063341000}'),d={name:"cs/async-fifo-cdc.md"};function p(C,a,f,c,D,m){const t=l("Mermaid");return r(),F("div",null,[a[2]||(a[2]=n('<h1 id="跨时钟域-fifo" tabindex="-1">跨时钟域 FIFO <a class="header-anchor" href="#跨时钟域-fifo" aria-label="Permalink to &quot;跨时钟域 FIFO&quot;">​</a></h1><div class="epigraph"><p>两个无关时钟之间不能直接采样多比特总线；用格雷码指针的异步 FIFO，让空满比较只过同步器，数据停在 RAM 里。</p><footer>—— 据 Cummings, Simulation and Synthesis Techniques for Asynchronous FIFO Design, SNUG 2002；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/reset-strategy">上一课</a>要求每域各自同步复位。组成课的<a href="/cs/clock-domain">时钟域</a>已禁止直接跨域打多比特。<a href="/cs/reset-strategy">复位</a>只解决控制初值。缺口是<strong>数据</strong>：生产者时钟写、消费者时钟读，如何不丢、不重复、不亚稳。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单比特过两级同步器。总线的各位亚稳窗口不同，会采到从未出现过的组合值。异步 FIFO：双端口 RAM，写指针在写时钟域递增，读指针在读时钟域递增。把指针编成<a href="/cs/gray-code">格雷码</a>再同步到对域，空/满在对域比较。缺口不是再定义亚稳，而是这套指针协议。</p><p><span class="marginnote">「亚稳」就是「触发器在时钟沿附近赶上信号变化太快，输出卡在不高不低的中间电平，过一小段时间才随机倒向某一边」。两个时钟互不相干，谁也说不准对方何时跳，任何直接采样都可能赶上这一瞬——同步器的全部工作就是把这种风险压缩到工程可忽略。</span></p><p>深度与几乎满/几乎空阈值是实现参数。本课钉格雷指针 + 同步，不把每家 IP 的参数表抄来。</p><h3 id="fifo-不是「加几个-ff-打一拍」" tabindex="-1">FIFO 不是「加几个 FF 打一拍」 <a class="header-anchor" href="#fifo-不是「加几个-ff-打一拍」" aria-label="Permalink to &quot;FIFO 不是「加几个 FF 打一拍」&quot;">​</a></h3><p>打一拍只在<strong>同一时钟</strong>下是流水线。跨域打一拍仍是非法多比特采样。把 CDC 理解成「插入寄存器就能过 STA」，STA 若把跨域当同步路径还会误报/漏报。应用 <code>set_clock_groups -asynchronous</code> 一类约束，功能正确靠 FIFO 结构。</p><p><span class="marginnote">Cummings SNUG 2002 异步 FIFO 是经典参考。Gray 码保证相邻指针只变 1 比特，同步后要么旧值要么新值，不会跳成第三种计数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写域：二进制写指针转格雷，写入指针寄存器，同步到读域。读域对称。满：同步过来的读指针与本地写指针比较（需多 1 位区分满空）。RAM 地址用二进制指针。复位：两域都回到空，且<a href="/cs/reset-strategy">同步释放</a>之后才能开始比指针。</p>',12)),(r(),o(A,null,{default:e(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20WCLK%5B%22%E5%86%99%E6%97%B6%E9%92%9F%E5%9F%9F%22%5D%20--%3E%20RAM%5B%22%E5%8F%8C%E5%8F%A3%20RAM%22%5D%0A%20%20RCLK%5B%22%E8%AF%BB%E6%97%B6%E9%92%9F%E5%9F%9F%22%5D%20--%3E%20RAM%0A%20%20WCLK%20--%3E%20WG%5B%22%E5%86%99%E6%8C%87%E9%92%88%E6%A0%BC%E9%9B%B7%22%5D%0A%20%20RCLK%20--%3E%20RG%5B%22%E8%AF%BB%E6%8C%87%E9%92%88%E6%A0%BC%E9%9B%B7%22%5D%0A%20%20WG%20--%3E%20SYNCR%5B%22%E5%90%8C%E6%AD%A5%E5%88%B0%E8%AF%BB%E5%9F%9F%22%5D%0A%20%20RG%20--%3E%20SYNCW%5B%22%E5%90%8C%E6%AD%A5%E5%88%B0%E5%86%99%E5%9F%9F%22%5D%0A%20%20SYNCR%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AFPGA%20LUT%20%E5%AE%9E%E7%8E%B0%E8%BF%99%E4%BA%9B%E5%9D%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"握手（valid/ready 加同步器）适合稀疏控制；突发数据用 FIFO 更合适。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：空/满比较为什么要多 1 位指针——4 位指针能数 16 个槽位，指针绕圈后「两指针相等」会出现两次含义：追平是空、赶上也是「相等」。最高那一多出来的位就是用来区分「落后一整圈」与「追到对面身后」的。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"后课 FPGA 有专用异步 FIFO 原语；ASIC 用库 RAM + 本课指针。形式验证可用断言：不满则写、不空则读、数据序保持。那是验证课的用例。DFT 扫描不要把跨域伪路径当成扫描移位违例——约束再次必须匹配。",-1)),a[7]||(a[7]=E("p",null,"指针为什么非要换成格雷码才准过同步器：",-1)),(r(),o(A,null,{default:e(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20BIN%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%E6%8C%87%E9%92%88%200111%20%E5%8A%A0%201%20%E5%8F%98%201000%22%5D%0A%20%20%20%20B1%5B%224%20%E4%B8%AA%E6%AF%94%E7%89%B9%E5%90%8C%E6%97%B6%E7%BF%BB%E8%BD%AC%22%5D%20--%3E%20B2%5B%22%E5%AF%B9%E5%9F%9F%E9%80%90%E4%BD%8D%E9%87%87%E6%A0%B7%20%E5%8F%AF%E8%83%BD%E6%8B%BC%E5%87%BA%E4%BB%8E%E6%9C%AA%E5%AD%98%E5%9C%A8%E8%BF%87%E7%9A%84%E4%B8%AD%E9%97%B4%E5%80%BC%22%5D%0A%20%20end%0A%20%20subgraph%20GRY%5B%22%E6%A0%BC%E9%9B%B7%E7%A0%81%E6%8C%87%E9%92%88%20%E5%90%8C%E4%B8%80%E6%AC%A1%E5%8A%A0%201%22%5D%0A%20%20%20%20G1%5B%22%E5%8F%AA%E6%9C%89%201%20%E4%B8%AA%E6%AF%94%E7%89%B9%E7%BF%BB%E8%BD%AC%22%5D%20--%3E%20G2%5B%22%E5%90%8C%E6%AD%A5%E5%90%8E%E9%9D%9E%E6%97%A7%E5%80%BC%E5%8D%B3%E6%96%B0%E5%80%BC%20%E4%B8%8D%E4%BC%9A%E5%87%BA%E7%8E%B0%E7%AC%AC%E4%B8%89%E7%A7%8D%E8%AE%A1%E6%95%B0%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解决相位已知的同源分频（可用同步 FIFO 或使能）。不讲 SerDes 弹性缓冲的全部 PCS。不把网络 socket 缓冲当成 CDC。</p><p><span class="marginnote">常见误区：初学者容易以为「跨域信号多打两拍就安全了」。两级同步器只能救单比特；多位总线各位走线延迟不一，同拍采样可能拼出任意组合——总线级的安全靠格雷指针或握手协议这类结构，不是靠多加寄存器。</span></p><p>后课默认：无关时钟之间的多比特数据走过格雷指针异步 FIFO；单比特才直接两级同步。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨域总线禁止直接采样；FIFO 把数据留在 RAM。</li><li>格雷指针只变 1 比特，可安全同步后比空满。</li><li>STA 约束异步组；功能靠结构。</li><li>出处：Cummings, SNUG 2002；Harris and Harris；Gray 码先修。</li></ul>',6))])}const g=B(d,[["render",p]]);export{h as __pageData,g as default};
